// Helpers shared by the EPUB parser and converter tests.
//
// The fixtures live next to this file in `test/data/document_conversion/
// fixtures/epub/` and are regenerated by `generate.py` there. PDF output is
// inspected with the structural reader from the DjVu tests (`parsePdf`), which
// understands the classic cross-reference table the `pdf` package writes for
// PDF 1.4 documents.

import 'dart:io';
import 'dart:typed_data';

import 'package:archive/archive.dart';
import 'package:image/image.dart' as img;
import 'package:saber/data/document_conversion/epub/epub_converter.dart';

import '../djvu/djvu_pdf_validate.dart';

export '../djvu/djvu_pdf_validate.dart' show ParsedPdf, PdfRef, parsePdf;

/// Root directory of the EPUB fixtures (relative to the repo root).
const epubFixtureRoot = 'test/data/document_conversion/fixtures/epub';

/// Root directory of the bundled EPUB fonts (relative to the repo root).
const epubFontRoot = 'assets/google_fonts/Atkinson_Hyperlegible_Next';

/// Reads a fixture EPUB as bytes.
Uint8List readEpubFixture(String name) =>
    File('$epubFixtureRoot/$name').readAsBytesSync();

/// Loads the bundled Atkinson Hyperlegible Next fonts for tests.
EpubPdfOptions readEpubFonts() {
  ByteData read(String name) =>
      ByteData.sublistView(File('$epubFontRoot/$name').readAsBytesSync());
  return EpubPdfOptions(
    regularFont: read('AtkinsonHyperlegibleNext-Regular.ttf'),
    boldFont: read('AtkinsonHyperlegibleNext-SemiBold.ttf'),
    italicFont: read('AtkinsonHyperlegibleNext-Italic.ttf'),
    boldItalicFont: read('AtkinsonHyperlegibleNext-SemiBoldItalic.ttf'),
  );
}

/// Builds an EPUB-shaped ZIP from UTF-8 text entries and binary [files].
Uint8List buildEpubZip(
  Map<String, String> entries, {
  Map<String, Uint8List> files = const {},
}) {
  final archive = Archive();
  archive.addFile(ArchiveFile.string('mimetype', 'application/epub+zip'));
  for (final entry in entries.entries) {
    archive.addFile(ArchiveFile.string(entry.key, entry.value));
  }
  for (final entry in files.entries) {
    archive.addFile(ArchiveFile.bytes(entry.key, entry.value));
  }
  return Uint8List.fromList(ZipEncoder().encode(archive));
}

/// A synthetic scan page: left-aligned dark bars with a ragged right edge,
/// the shape the orientation scorer is tuned for.
img.Image textLikePage({int width = 260, int height = 200}) {
  final image = img.Image(width: width, height: height);
  img.fill(image, color: img.ColorRgb8(255, 255, 255));
  final ink = img.ColorRgb8(20, 20, 20);
  img.fillRect(image, x1: 20, y1: 14, x2: 140, y2: 26, color: ink);
  const lengths = [200, 170, 210, 150, 190, 120, 205, 175, 160, 195, 140, 185];
  var y = 44;
  for (final length in lengths) {
    if (y + 7 >= height - 8) break;
    img.fillRect(
      image,
      x1: 20,
      y1: y,
      x2: (20 + length).clamp(0, width),
      y2: y + 7,
      color: ink,
    );
    y += 13;
  }
  return image;
}

/// Encodes [image] as EPUB-style JPEG page bytes.
Uint8List scanJpeg(img.Image image) =>
    Uint8List.fromList(img.encodeJpg(image));

/// Builds a scan-only EPUB whose single spine document references [images]
/// (archive paths, typically under `OEBPS/`) in reading order.
Uint8List buildScanEpub(Map<String, Uint8List> images) {
  final manifest = StringBuffer();
  final body = StringBuffer();
  var index = 0;
  for (final path in images.keys) {
    final href = path.split('/').last;
    manifest.write(
      '<item id="i$index" href="$href" media-type="image/jpeg"/>',
    );
    body.write('<img src="$href"/>');
    index++;
  }
  return buildEpubZip(
    {
      'META-INF/container.xml':
          '<?xml version="1.0"?><container version="1.0" '
          'xmlns="urn:oasis:names:tc:opendocument:xmlns:container">'
          '<rootfiles><rootfile full-path="OEBPS/package.opf" '
          'media-type="application/oebps-package+xml"/></rootfiles>'
          '</container>',
      'OEBPS/package.opf':
          '<?xml version="1.0"?><package '
          'xmlns="http://www.idpf.org/2007/opf" version="3.0" '
          'unique-identifier="uid"><metadata '
          'xmlns:dc="http://purl.org/dc/elements/1.1/">'
          '<dc:identifier id="uid">urn:uuid:scan</dc:identifier>'
          '<dc:title>Scan</dc:title></metadata><manifest>'
          '<item id="scan" href="scan.xhtml" '
          'media-type="application/xhtml+xml"/>$manifest</manifest>'
          '<spine><itemref idref="scan"/></spine></package>',
      'OEBPS/scan.xhtml':
          '<?xml version="1.0"?><html '
          'xmlns="http://www.w3.org/1999/xhtml"><head>'
          '<title>Scan</title></head><body>'
          '$body</body></html>',
    },
    files: images,
  );
}

/// One page of a converted PDF.
({int id, Map<String, Object?> dict}) pageAt(ParsedPdf pdf, int index) {
  final catalog = pdf.object((pdf.trailer['Root']! as PdfRef).id).dict;
  final pages = pdf.object((catalog['Pages']! as PdfRef).id).dict;
  final kids = (pages['Kids']! as List).cast<PdfRef>();
  return (id: kids[index].id, dict: pdf.object(kids[index].id).dict);
}

/// The inflated content stream of [page] as text.
String contentOf(ParsedPdf pdf, Map<String, Object?> page) =>
    pdf.contentText(pdf.object((page['Contents']! as PdfRef).id));

/// One entry of a PDF outline read back from the file.
class ParsedPdfOutline {
  ParsedPdfOutline({
    required this.title,
    required this.pageIndex,
    required this.children,
  });

  final String title;
  final int pageIndex;
  final List<ParsedPdfOutline> children;
}

/// One link annotation read back from a page.
class ParsedPdfLink {
  ParsedPdfLink({
    required this.pageIndex,
    required this.rect,
    this.destination,
    this.url,
  });

  /// 0-based page the annotation sits on.
  final int pageIndex;

  /// `[left, bottom, right, top]`.
  final List<double> rect;

  /// Named destination of a `GoTo` action.
  final String? destination;

  /// URL of a `URI` action.
  final String? url;
}

/// The catalog dictionary of [pdf] with slash-free keys.
Map<String, Object?> pdfCatalog(ParsedPdf pdf) =>
    _dict(pdf, pdf.trailer['Root']);

/// The document information dictionary, when present.
Map<String, Object?>? pdfInfo(ParsedPdf pdf) {
  final info = pdf.trailer['Info'];
  return info == null ? null : _dict(pdf, info);
}

/// Object ids of the pages, in document order.
List<int> pdfPageObjectIds(ParsedPdf pdf) {
  final catalog = pdfCatalog(pdf);
  final out = <int>[];
  void visit(Object? node) {
    final dict = _dict(pdf, node);
    if (dict['Type'] == 'Pages') {
      for (final kid in _list(dict['Kids'])) {
        visit(kid);
      }
    } else {
      out.add((node! as PdfRef).id);
    }
  }

  visit(catalog['Pages']);
  return out;
}

/// Named destinations mapped to 0-based page indices.
Map<String, int> pdfNamedDestinations(ParsedPdf pdf) {
  final catalog = pdfCatalog(pdf);
  final names = catalog['Names'];
  if (names == null) return const {};
  final dests = _dict(pdf, names)['Dests'];
  if (dests == null) return const {};
  final array = _list(_dict(pdf, dests)['Names']);
  final pages = _pageIndexById(pdf);
  final out = <String, int>{};
  for (var i = 0; i + 1 < array.length; i += 2) {
    final name = array[i];
    if (name is! String) continue;
    final page = _destinationPage(pdf, array[i + 1], pages);
    if (page != null) out[name] = page;
  }
  return out;
}

/// The PDF outline tree.
List<ParsedPdfOutline> pdfOutline(ParsedPdf pdf) {
  final catalog = pdfCatalog(pdf);
  final outlines = catalog['Outlines'];
  if (outlines == null) return const [];
  final root = _dict(pdf, outlines);
  final named = pdfNamedDestinations(pdf);
  final pages = _pageIndexById(pdf);

  List<ParsedPdfOutline> siblings(Object? first) {
    final out = <ParsedPdfOutline>[];
    Object? node = first;
    while (node is PdfRef) {
      final dict = pdf.object(node.id).dict;
      final action = dict['A'];
      final dest = dict['Dest'] ?? (action is Map ? action['D'] : null);
      out.add(
        ParsedPdfOutline(
          title: dict['Title'] as String? ?? '',
          pageIndex: dest is String
              ? (named[dest] ?? 0)
              : (_destinationPage(pdf, dest, pages) ?? 0),
          children: siblings(dict['First']),
        ),
      );
      node = dict['Next'];
    }
    return out;
  }

  return siblings(root['First']);
}

/// Every link annotation of the document, in page order.
List<ParsedPdfLink> pdfLinks(ParsedPdf pdf) {
  final out = <ParsedPdfLink>[];
  final pages = pdfPageObjectIds(pdf);
  for (var index = 0; index < pages.length; index++) {
    final annots = _list(pdf.object(pages[index]).dict['Annots']);
    for (final ref in annots) {
      if (ref is! PdfRef) continue;
      final dict = pdf.object(ref.id).dict;
      final action = dict['A'];
      String? destination;
      String? url;
      if (action is Map) {
        if (action['S'] == 'GoTo' && action['D'] is String) {
          destination = action['D']! as String;
        }
        if (action['S'] == 'URI' && action['URI'] is String) {
          url = action['URI']! as String;
        }
      }
      out.add(
        ParsedPdfLink(
          pageIndex: index,
          rect: [
            for (final value in _list(dict['Rect']))
              if (value is num) value.toDouble(),
          ],
          destination: destination,
          url: url,
        ),
      );
    }
  }
  return out;
}

/// Every visible image XObject dictionary in the document.
///
/// Soft masks are images too, but they are referenced from the image they
/// mask, so they are filtered out here.
List<Map<String, Object?>> pdfImages(ParsedPdf pdf) {
  final masks = <int>{};
  for (final record in pdf.objects.values) {
    final value = record.value;
    if (value is Map && value['SMask'] is PdfRef) {
      masks.add((value['SMask']! as PdfRef).id);
    }
  }
  return [
    for (final record in pdf.objects.values)
      if (record.value is Map &&
          (record.value! as Map)['Subtype'] == 'Image' &&
          !masks.contains(record.id))
        record.dict,
  ];
}

Map<int, int> _pageIndexById(ParsedPdf pdf) {
  final pages = pdfPageObjectIds(pdf);
  return {for (var i = 0; i < pages.length; i++) pages[i]: i};
}

int? _destinationPage(
  ParsedPdf pdf,
  Object? destination,
  Map<int, int> pageIndex,
) {
  if (destination is PdfRef) {
    // Either a destination array or a destination dictionary object.
    final dict = pdf.object(destination.id).dict;
    return _destinationPage(pdf, dict['D'] ?? dict, pageIndex);
  }
  if (destination is Map) {
    return _destinationPage(pdf, destination['D'], pageIndex);
  }
  if (destination is List && destination.isNotEmpty) {
    final first = destination.first;
    if (first is PdfRef) return pageIndex[first.id];
  }
  return null;
}

Map<String, Object?> _dict(ParsedPdf pdf, Object? value) {
  if (value is PdfRef) return pdf.object(value.id).dict;
  if (value is Map<String, Object?>) return value;
  if (value is Map) return value.cast<String, Object?>();
  throw StateError('Expected a dictionary, got $value');
}

List<Object?> _list(Object? value) =>
    value is List ? value.cast<Object?>() : const [];
